export const messagingState={mode:'disabled',username:'finfolk.com.au',enabledCommands:['ping','help'],pilotSenderIds:[],health:{status:'attention',issues:['uncertain_replies'],pendingReplies:1,uncertainReplies:1,failedReplies:1},blockers:['token_missing'],checks:{authorization:false,subscription:false},lastWebhookAt:null,lastCommandAt:null,lastProviderAcceptedAt:null};
export const accountModule=`
let user=sessionStorage.getItem('fixture:guest')?null:{uid:'alice',emailVerified:!sessionStorage.getItem('fixture:unverified')},listeners=new Set(),subscriptions=new Map();window.accountCalls=[];
let profile={displayName:'Alice',bio:'Freediving and training.',instagram:'https://www.instagram.com/alice.dives/',tiktok:'',open:false,beaches:['bondi'],sharing:{visits:true},activities:['freediving'],availability:['weekend mornings'],experience:'comfortable',depthGoal:12};
let checkinRace=false;let visits=[{beach_id:'bondi',name:'Bondi Beach',day:'2026-10-30'}],connections=[{id:'bob',name:'Bob',status:'pending',requested_by:'bob'}],blocks=[{id:'eve',name:'Eve'}],messaging=${JSON.stringify(messagingState)};
const notify=()=>listeners.forEach(fn=>fn(user)),emit=(name,data)=>{for(const fn of subscriptions.get(name)||[])fn({status:'ready',data:structuredClone(data)})};window.signOutAccountFixture=()=>{user=null;notify()};window.updateCheckinsFixture=()=>{visits=[...visits,{beach_id:'portsea',name:'Portsea Beach',day:'2026-10-31'}];emit('myCheckins',visits)};
export const api={get user(){return user},observe(fn){listeners.add(fn);queueMicrotask(()=>fn(user));return ()=>listeners.delete(fn)},async subscribe(name,values,fn){window.accountSubscriptions=(window.accountSubscriptions||0)+1;if(!subscriptions.has(name))subscriptions.set(name,new Set());subscriptions.get(name).add(fn);if(name==='myCheckins'||name==='me')queueMicrotask(()=>fn({status:'ready',data:structuredClone(name==='myCheckins'?visits:{id:'alice',profile})}));return ()=>subscriptions.get(name).delete(fn)},async call(action,value={}){window.accountCalls.push({action,value});
 if(action==='me'){if(sessionStorage.getItem('fixture:deleted-account'))throw Error('Account has been deleted.');if(window.delayAccountMe){window.delayAccountMe=false;await new Promise(resolve=>window.releaseAccountMe=resolve);}return {id:'alice',profile:structuredClone(profile)}};
 if(action==='postStatus')return {admin:false,enabled:false};
 if(action==='myCheckins'){const snapshot=structuredClone(visits);if(sessionStorage.getItem('fixture:checkin-race')&&!checkinRace){checkinRace=true;visits.push({beach_id:'portsea',name:'Portsea Beach',day:'2026-11-02'});emit('myCheckins',visits);}return snapshot;}
 if(action==='checkin'){if(window.failCheckin)throw Error('Check-in connection failed');visits.push({beach_id:value.beachId,name:value.beachId==='bondi'?'Bondi Beach':'Portsea Beach',day:'2026-11-01'});emit('myCheckins',visits);return {};}
 if(action==='removeCheckin'){visits=visits.filter(x=>!(x.beach_id===value.beachId&&x.day===value.day));emit('myCheckins',visits);return {};}
 if(action==='connections'){if(window.delayConnections){window.delayConnections=false;await new Promise(resolve=>window.releaseConnections=resolve);}return structuredClone(connections)};
 if(action==='blocks')return structuredClone(blocks);
 if(action==='preferences'){profile={...profile,...value.profile};emit('me',{id:'alice',profile});sessionStorage.setItem('fixture:saved-account',JSON.stringify(value.profile));return {profile:structuredClone(profile)}};
 if(action==='connection'){connections=connections.map(x=>x.id===value.target?{...x,status:'accepted'}:x);return {};}
 if(action==='block'){connections=connections.filter(x=>x.id!==value.target);return {};}
 if(action==='unblock'){blocks=blocks.filter(x=>x.id!==value.target);return {};}
 if(action==='instagramStatus')return {enabled:false,admin:false,total:0,connection:null};
 if(action==='instagramCommandStatus')return {enabled:false,admin:false,commands:[]};
 if(['instagramActions','myPosts','tripList'].includes(action))return [];
 throw Error('Unexpected account fixture '+action);
},async request(path,options={}){window.accountCalls.push({path,options});if(path==='/v1/me/site-submissions')return {submissions:[]};if(!sessionStorage.getItem('fixture:messaging-admin'))throw Object.assign(Error('Access denied'),{status:403});if(options.method==='PUT'){if(window.failMessaging)throw Error('Uncertain response');messaging={...messaging,...options.body};return {};}
 if(path.includes('/events?'))return {events:[{id:'failed',command:'ping',state:'failed',requestId:'request-failed',senderId:'100',receivedAt:'2026-10-30T00:00:00Z',reply:{state:'failed'}},{id:'uncertain',command:'help',state:'completed',requestId:'request-uncertain',senderId:'200',receivedAt:'2026-10-30T00:00:00Z',reply:{state:'uncertain'}}]};
 if(path.endsWith('/retry'))return {};
 if(path.endsWith('/authorization'))return {authorizationUrl:'https://authorization.invalid/'};
 return structuredClone(messaging);
},async signOut(){user=null;notify()},async verify(){window.accountCalls.push({action:'verify'})},async verifyCode(code){sessionStorage.removeItem('fixture:unverified');window.accountCalls.push({action:'verifyCode',code});user={...user,emailVerified:true};notify()},async refresh(){notify()},async reauthenticate(password){window.accountCalls.push({action:'reauthenticate',password});if(password==='wrong')throw Error('Reauthentication failed')},async deleteAccount(password){window.accountCalls.push({action:'deleteAccount',password})},async email(email,password){if(password==='wrong')throw Error('Invalid credentials');user={uid:'alice',emailVerified:true};notify()},async google(){window.accountCalls.push({action:'google'})},async reset(email){window.accountCalls.push({action:'reset',email})},async resetPassword(token,password){window.accountCalls.push({action:'resetPassword',token,password})},auth:{async deleteUser(value){window.accountCalls.push({action:'finishDelete',value});user=null;notify();return {}},signUp:{async email(value){window.accountCalls.push({action:'signup',value});user={uid:'alice',emailVerified:false};notify();return {}}}}};
export async function createLogbookClient(){return api;}
`;
export async function mockAccount(page,base){await page.route('**/neon-config.json*',r=>r.fulfill({json:{enabled:true,googleEnabled:true,authUrl:'https://auth.invalid',apiUrl:base+'/'}}));await page.route('**/neon-client.js',r=>r.fulfill({contentType:'text/javascript',body:accountModule}));}
